CARDIO.register({"item":"d112","meta":{"num":"d112","label":"112","spe":"dermato","short":"Bulleuses auto-immunes","title":"Dermatoses bulleuses auto-immunes","section":"D","chapter":2,"pages":"54-68","sdd":[{"num":82,"label":"Bulles, éruption bulleuse"},{"num":85,"label":"Érythème"},{"num":88,"label":"Prurit"},{"num":91,"label":"Anomalies des muqueuses"},{"num":219,"label":"Hyperéosinophilie"},{"num":180,"label":"Interprétation du CR anapath"},{"num":328,"label":"Annonce d'une maladie chronique"}]},"objectives":[{"id":"d112-obj-01","rank":"A","rubric":"Définition","title":"Définition d'une dermatose bulleuse auto-immune","desc":""},{"id":"d112-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Savoir diagnostiquer une dermatose bulleuse auto-immune","desc":"Bulles, érosions post-bulleuses, érosions muqueuses, décollement en linge mouillé, signe de Nikolsky → histologie cutanée et IF directe"},{"id":"d112-obj-03","rank":"B","rubric":"Diagnostic positif","title":"Savoir argumenter le diagnostic des différentes maladies bulleuses auto-immunes","desc":"Groupe des pemphigoïdes versus groupe des pemphigus, distinguer bulle sous-épidermique et bulle intra-épidermique"},{"id":"d112-obj-04","rank":"A","rubric":"Examens complémentaires","title":"Connaître l'intérêt de la biopsie devant une dermatose bulleuse","desc":""},{"id":"d112-obj-05","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître une lésion bulleuse","desc":""},{"id":"d112-obj-06","rank":"B","rubric":"Contenu multimédia","title":"Photographie de lésions cutanéo-muqueuses de pemphigus vulgaire","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d112-qroc-001","type":"QROC","rank":"A","objective":"d112-obj-01","tags":["diagnostic"],"difficulty":1,"question":"Quelles trois catégories d'examens doivent être combinées pour diagnostiquer une dermatose bulleuse auto-immune ?","answer":"Clinique, anatomopathologique et immunopathologique","accept":["clinique, histologie et immunofluorescence","examen clinique, histologie, immunofluorescence","clinique histologie immunofluorescence"],"keywords":["clinique","immun"],"explanation":"Le diagnostic d'une DBAI associe l'examen clinique, l'examen anatomopathologique d'une biopsie cutanée et l'examen immunopathologique (immunofluorescence directe, recherche d'anticorps).","src":"p. 55, 67"},{"id":"d112-qroc-002","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["épidémiologie"],"difficulty":1,"question":"Quelle est la dermatose bulleuse auto-immune la plus fréquente ?","answer":"La pemphigoïde bulleuse","accept":["pemphigoïde bulleuse","la pemphigoïde bulleuse"],"keywords":["pemphigoïde"],"explanation":"La pemphigoïde bulleuse est la plus fréquente des DBAI ; elle touche surtout les sujets âgés.","src":"p. 59, 67"},{"id":"d112-qroc-003","type":"QROC","rank":"A","objective":"d112-obj-05","tags":["définition","clinique"],"difficulty":1,"question":"Quelle taille minimale définit une bulle ?","answer":"Plus de 5 mm","accept":["5 mm","supérieure à 5 mm","5mm"],"keywords":["5"],"explanation":"Une bulle est une lésion élémentaire liquidienne superficielle, au contenu clair ou séro-hématique, de taille supérieure à 5 mm ; elle peut siéger sur la peau ou les muqueuses.","src":"p. 55"},{"id":"d112-qroc-004","type":"QROC","rank":"A","objective":"d112-obj-05","tags":["clinique"],"difficulty":1,"question":"Comment appelle-t-on le décollement cutané provoqué par un frottement appuyé sur la peau saine ?","answer":"Le signe de Nikolsky","accept":["nikolsky","signe de nikolsky"],"keywords":["nikolsky"],"explanation":"Le signe de Nikolsky traduit un décollement intra-épidermique (acantholyse) ; il est positif dans le pemphigus.","src":"p. 55"},{"id":"d112-qroc-005","type":"QROC","rank":"A","objective":"d112-obj-05","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Quel aspect a une bulle sous-épidermique récente ?","answer":"Une bulle tendue","accept":["tendue","bulle tendue","bulles tendues"],"keywords":["tendu"],"explanation":"Le clivage entre le derme et l'épiderme donne une bulle tendue, car son toit est constitué par l'épiderme intact ; son contenu est clair ou hématique.","src":"p. 55"},{"id":"d112-qroc-006","type":"QROC","rank":"A","objective":"d112-obj-05","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Quel aspect a une bulle intra-épidermique récente ?","answer":"Une bulle flasque et fragile","accept":["flasque","bulle flasque","flasque et fragile","bulles flasques"],"keywords":["flasque"],"explanation":"Le détachement des kératinocytes entre eux donne une bulle flasque et fragile, car son toit est très fin.","src":"p. 55"},{"id":"d112-qroc-007","type":"QROC","rank":"A","objective":"d112-obj-02","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quel examen met en évidence l'origine auto-immune d'une maladie bulleuse ?","answer":"L'immunofluorescence directe (IFD) d'une biopsie","accept":["immunofluorescence directe","ifd","if directe"],"keywords":["immunofluorescence","direct"],"explanation":"L'IFD d'une biopsie de peau ou de muqueuse périlésionnelle montre des dépôts in vivo d'IgG et/ou d'IgA et/ou de C3.","src":"p. 56"},{"id":"d112-qroc-008","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["paraclinique"],"difficulty":1,"question":"Quel aspect donne l'IFD dans le pemphigus ?","answer":"Des dépôts en mailles de filet (résille) autour des kératinocytes","accept":["mailles de filet","maille de filet","résille","en résille"],"keywords":[],"explanation":"Dans le pemphigus (DBAI intra-épidermique), les dépôts d'IgG et de C3 entourent les kératinocytes en mailles de filet.","src":"p. 56"},{"id":"d112-qroc-009","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["paraclinique"],"difficulty":1,"question":"Quel aspect donne l'IFD dans les dermatoses bulleuses auto-immunes sous-épidermiques ?","answer":"Des dépôts linéaires le long de la jonction dermo-épidermique","accept":["linéaire","dépôts linéaires","linéaire le long de la membrane basale"],"keywords":["linéaire"],"explanation":"Les dépôts sont linéaires le long de la jonction dermo-épidermique (membrane basale), à la différence des mailles de filet du pemphigus.","src":"p. 56, 59"},{"id":"d112-qroc-010","type":"QROC","rank":"A","objective":"d112-obj-04","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Sur quel type de lésion réalise-t-on la biopsie destinée à l'histologie d'une dermatose bulleuse ?","answer":"Une bulle intacte et récente","accept":["bulle intacte et récente","bulle récente","bulle intacte"],"keywords":["intacte","récente"],"explanation":"La biopsie, sous anesthésie locale, porte sur une bulle cutanée intacte et récente (ou sur le bord d'une érosion muqueuse) pour l'examen histopathologique.","src":"p. 59"},{"id":"d112-qroc-011","type":"QROC","rank":"A","objective":"d112-obj-04","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Où prélève-t-on la biopsie destinée à l'immunofluorescence directe ?","answer":"En zone périlésionnelle (peau ou muqueuse)","accept":["périlésionnelle","péri-lésionnelle","peau périlésionnelle"],"keywords":["périlésionnel"],"explanation":"L'IFD se fait sur une biopsie de peau ou de muqueuse périlésionnelle, qui montre les anticorps fixés in vivo (anti-membrane basale ou anti-SIC).","src":"p. 56, 59"},{"id":"d112-qroc-012","type":"QROC","rank":"A","objective":"d112-obj-02","tags":["diagnostic","urgence"],"difficulty":2,"question":"Un patient sous médicament présente une éruption bulleuse à début brutal, avec signes généraux et atteinte muqueuse souvent inaugurale. Quel diagnostic grave faut-il éliminer ?","answer":"Une toxidermie bulleuse (Lyell, Stevens-Johnson)","accept":["toxidermie bulleuse","syndrome de lyell","stevens-johnson","lyell","nécrolyse épidermique toxique"],"keywords":["toxidermie"],"explanation":"La toxidermie bulleuse (syndromes de Lyell et de Stevens-Johnson) se reconnaît à son début brutal, son évolution rapide, ses signes généraux imposant une hospitalisation en urgence, l'atteinte muqueuse fréquente et la prise de médicaments dans le délai d'imputabilité.","src":"p. 56"},{"id":"d112-qroc-013","type":"QROC","rank":"A","objective":"d112-obj-02","tags":["urgence"],"difficulty":1,"question":"Quelle prise en charge impose une dermatose bulleuse auto-immune étendue et/ou rapidement évolutive ?","answer":"Une hospitalisation en service spécialisé de dermatologie","accept":["hospitalisation","hospitalisation en service spécialisé","hospitalisation en dermatologie"],"keywords":["hospitalis"],"explanation":"Toute forme étendue ou rapidement évolutive impose l'hospitalisation en service spécialisé.","src":"p. 58, 67"},{"id":"d112-qroc-014","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["épidémiologie"],"difficulty":1,"question":"Quel est l'âge moyen de survenue de la pemphigoïde bulleuse ?","answer":"Environ 80 ans (sujet âgé)","accept":["80 ans","80","plus de 70 ans","70 ans"],"keywords":["80"],"explanation":"La pemphigoïde bulleuse touche surtout les sujets âgés (80 ans en moyenne ; plus de 70 ans dans le tableau comparatif), alors que le pemphigus survient plutôt entre 40 et 50 ans.","src":"p. 59"},{"id":"d112-qroc-015","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["clinique"],"difficulty":1,"question":"Quel symptôme marque le début d'une pemphigoïde bulleuse, avant les bulles ?","answer":"Un prurit généralisé et intense","accept":["prurit","prurit généralisé","prurit intense"],"keywords":["prurit"],"explanation":"La pemphigoïde bulleuse débute par un prurit généralisé et intense, avec des placards eczématiformes ou urticariens, puis apparaissent des bulles tendues.","src":"p. 59"},{"id":"d112-qroc-016","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["clinique"],"difficulty":1,"question":"Dans quelle dermatose bulleuse auto-immune le signe de Nikolsky est-il positif ?","answer":"Le pemphigus","accept":["pemphigus","pemphigus vulgaire"],"keywords":["pemphigus"],"explanation":"Le signe de Nikolsky est positif dans le pemphigus (décollement intra-épidermique) et absent dans la pemphigoïde bulleuse.","src":"p. 55, 59"},{"id":"d112-qroc-017","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["clinique"],"difficulty":2,"question":"Dans la pemphigoïde bulleuse, comment est la peau péribulleuse ?","answer":"Érythémateuse ou urticarienne (eczématiforme)","accept":["urticarienne","érythémateuse","eczématiforme","urticarienne ou érythémateuse"],"keywords":[],"explanation":"Les bulles tendues de la pemphigoïde bulleuse siègent sur une peau érythémateuse, eczématiforme ou urticarienne ; dans le pemphigus, les bulles flasques siègent sur une peau saine.","src":"p. 58-59"},{"id":"d112-qroc-018","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["biologie","diagnostic"],"difficulty":1,"question":"Quelle anomalie de la numération-formule sanguine est fréquente dans la pemphigoïde bulleuse ?","answer":"Une hyperéosinophilie","accept":["hyperéosinophilie","éosinophilie"],"keywords":["éosinophil"],"explanation":"L'hyperéosinophilie est fréquente ; l'histologie montre une bulle sous-épidermique riche en éosinophiles.","src":"p. 60"},{"id":"d112-qroc-019","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quel aspect histologique caractérise la pemphigoïde bulleuse ?","answer":"Une bulle sous-épidermique à éosinophiles, sans acantholyse","accept":["bulle sous-épidermique","sous-épidermique","sous épidermique"],"keywords":["sous","épidermique"],"explanation":"L'histologie montre une bulle sous-épidermique contenant des éosinophiles, sans acantholyse ni nécrose des kératinocytes, avec un infiltrat dermique riche en éosinophiles.","src":"p. 60"},{"id":"d112-qroc-020","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["complications"],"difficulty":1,"question":"Quel est le taux de mortalité à 1 an de la pemphigoïde bulleuse ?","answer":"30 à 40 %","accept":["30 à 40","30-40 %","entre 30 et 40 %"],"keywords":["30","40"],"explanation":"La pemphigoïde bulleuse est grave : mortalité de 30 à 40 % à 1 an, surtout par complications infectieuses ou cardiovasculaires favorisées par les traitements et le terrain âgé.","src":"p. 61"},{"id":"d112-qroc-021","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":1,"question":"Quel dermocorticoïde fort est utilisé dans le traitement de la pemphigoïde bulleuse ?","answer":"Le propionate de clobétasol","accept":["clobétasol","propionate de clobétasol"],"keywords":["clobétasol"],"explanation":"Le propionate de clobétasol (20 à 40 g/jour) a une efficacité similaire à la corticothérapie générale, avec une meilleure tolérance.","src":"p. 61"},{"id":"d112-qroc-022","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"question":"Quelle quantité quotidienne de propionate de clobétasol applique-t-on dans la pemphigoïde bulleuse ?","answer":"20 à 40 g/jour","accept":["20 à 40 g","20-40 g/jour","20 à 40"],"keywords":["20","40"],"explanation":"On applique 20 à 40 g/jour de clobétasol, puis la dose est diminuée progressivement par paliers ; le traitement dure 6 à 12 mois.","src":"p. 61"},{"id":"d112-qroc-023","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"question":"Quel avantage la corticothérapie locale forte a-t-elle sur la corticothérapie générale dans la pemphigoïde bulleuse ?","answer":"Une meilleure tolérance (moins d'effets secondaires, moindre mortalité)","accept":["meilleure tolérance","mieux tolérée","moins d'effets secondaires","baisse de la mortalité"],"keywords":["tolérance"],"explanation":"À efficacité similaire, la corticothérapie locale forte est mieux tolérée : moins d'effets secondaires et baisse de la mortalité.","src":"p. 61"},{"id":"d112-qroc-024","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"question":"Quelle dose de prednisone peut être utilisée en première intention dans une pemphigoïde bulleuse peu étendue (moins de 10 bulles par jour) ?","answer":"0,5 à 0,75 mg/kg/jour","accept":["0,5 à 0,75 mg/kg/jour","0,5-0,75 mg/kg","0,5 à 0,75 mg/kg"],"keywords":["0,5","0,75"],"explanation":"Pour les atteintes limitées (< 10 bulles/jour), la prednisone à 0,5-0,75 mg/kg/jour peut être utilisée en première intention, avec une dégression progressive sur plusieurs mois.","src":"p. 61"},{"id":"d112-qroc-025","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"question":"Outre la corticothérapie, quelles trois mesures générales propres à toute maladie bulleuse faut-il mettre en route ?","answer":"Bains antiseptiques, hydratation, nutrition hypercalorique","accept":["bains antiseptiques, hydratation et nutrition hypercalorique","bains antiseptiques, hydratation, nutrition hypercalorique"],"keywords":["antiseptique","hydratation","hypercalor"],"explanation":"Mesures propres à toute maladie bulleuse : bains antiseptiques, hydratation compensant les pertes hydro-électrolytiques (en évitant si possible la voie veineuse, à cause du risque infectieux) et nutrition hypercalorique compensant les pertes protéiques.","src":"p. 61"},{"id":"d112-qroc-026","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["physiopathologie"],"difficulty":1,"question":"Contre quelles structures les autoanticorps du pemphigus sont-ils dirigés ?","answer":"Les protéines des desmosomes","accept":["desmosomes","desmosome"],"keywords":["desmosom"],"explanation":"Les autoanticorps du pemphigus visent des protéines des desmosomes et provoquent l'acantholyse, donc un clivage intra-épidermique.","src":"p. 64"},{"id":"d112-qroc-027","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["physiopathologie"],"difficulty":1,"question":"Comment appelle-t-on le détachement des kératinocytes les uns des autres, responsable du clivage intra-épidermique du pemphigus ?","answer":"L'acantholyse","accept":["acantholyse","l'acantholyse"],"keywords":["acantholy"],"explanation":"L'acantholyse est la perte de cohésion des kératinocytes, due à l'altération des desmosomes par des autoanticorps.","src":"p. 55, 64, 66"},{"id":"d112-qroc-028","type":"QROC","rank":"A","objective":"d112-obj-06","tags":["clinique"],"difficulty":1,"question":"Par quelle atteinte débute souvent le pemphigus vulgaire ?","answer":"Des érosions muqueuses, surtout buccales","accept":["érosions buccales","érosions muqueuses","atteinte muqueuse","lésions muqueuses","érosions de la muqueuse buccale"],"keywords":["muqueu"],"explanation":"Le pemphigus vulgaire débute souvent de façon insidieuse par des érosions buccales douloureuses et traînantes, gênant l'alimentation (dysphagie) ; l'atteinte cutanée n'apparaît que plusieurs semaines ou mois plus tard.","src":"p. 64, 67"},{"id":"d112-qroc-029","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Où se situe le clivage dans le pemphigus vulgaire ?","answer":"Dans la couche suprabasale de l'épiderme","accept":["suprabasal","suprabasale","intra-épidermique suprabasal"],"keywords":["suprabasal"],"explanation":"Le pemphigus vulgaire donne une bulle intra-épidermique suprabasale avec acantholyse ; dans les pemphigus superficiels, le clivage est sous-corné.","src":"p. 66"},{"id":"d112-qroc-030","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["complications"],"difficulty":2,"question":"À quoi est principalement due la mortalité (environ 10 %) du pemphigus ?","answer":"Aux complications iatrogènes (du traitement)","accept":["complications iatrogènes","iatrogène","effets du traitement"],"keywords":["iatrog"],"explanation":"La mortalité du pemphigus, autour de 10 %, est principalement due aux complications iatrogènes du traitement.","src":"p. 67"},{"id":"d112-qroc-031","type":"QROC","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":1,"question":"Quelle dose de prednisone constitue le traitement d'attaque du pemphigus ?","answer":"1 à 1,5 mg/kg/jour","accept":["1 à 1,5 mg/kg/jour","1-1,5 mg/kg","1 à 1,5 mg/kg"],"keywords":["1,5"],"explanation":"Le traitement d'attaque du pemphigus est une corticothérapie générale à forte dose : prednisone 1 à 1,5 mg/kg/jour.","src":"p. 67"},{"id":"d112-qroc-032","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["physiopathologie","biologie"],"difficulty":2,"question":"Comment appelle-t-on les anticorps déposés à la périphérie des kératinocytes dans les pemphigus ?","answer":"Anticorps anti-substance intercellulaire (anti-SIC)","accept":["anti-sic","anti-substance intercellulaire"],"keywords":["intercellul"],"explanation":"Les anticorps dirigés contre la jonction dermo-épidermique sont dits anti-membrane basale ; ceux déposés à la périphérie des kératinocytes dans les pemphigus sont des anticorps anti-substance intercellulaire (anti-SIC).","src":"p. 56"},{"id":"d112-qroc-033","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["physiopathologie","biologie"],"difficulty":2,"question":"Quelle est la cible antigénique du pemphigus vulgaire ?","answer":"La desmogléine 3","accept":["desmogléine 3","dsg3","dsg 3"],"keywords":["desmogl","3"],"explanation":"Dans le pemphigus vulgaire, les autoanticorps reconnaissent la desmogléine 3 (la desmogléine 1 dans le pemphigus superficiel).","src":"p. 58, 66"},{"id":"d112-qroc-034","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["physiopathologie","biologie"],"difficulty":2,"question":"Quelle est la cible antigénique du pemphigus superficiel ?","answer":"La desmogléine 1","accept":["desmogléine 1","dsg1","dsg 1"],"keywords":["desmogl","1"],"explanation":"La desmogléine 1 est la cible du pemphigus superficiel, la desmogléine 3 celle du pemphigus vulgaire.","src":"p. 58, 66"},{"id":"d112-qroc-035","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["physiopathologie","biologie"],"difficulty":2,"question":"Quelles sont les cibles antigéniques de la pemphigoïde bulleuse ?","answer":"BP230 (BPAG1) et BP180 (BPAG2)","accept":["bp230 et bp180","bp180 et bp230","bpag1 et bpag2","bpag2 et bpag1","bp230, bp180"],"keywords":["bp230","bp180"],"explanation":"La pemphigoïde bulleuse vise BPAG1 (BP230) et BPAG2 (BP180), protéines de la jonction dermo-épidermique ; des anticorps anti-membrane basale de classe IgG sont détectés dans 80 % des sérums.","src":"p. 58-60"},{"id":"d112-qroc-036","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["traitement"],"difficulty":1,"question":"Quel anticorps monoclonal anti-CD20 peut être proposé en première intention dans le pemphigus ?","answer":"Le rituximab","accept":["rituximab","le rituximab"],"keywords":["rituximab"],"explanation":"Le rituximab peut être proposé en première intention pour réduire la dose et la durée de la corticothérapie, et ses effets secondaires.","src":"p. 67"},{"id":"d112-qroc-037","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quels sont les trois grands types de pemphigus ?","answer":"Vulgaire, superficiels et paranéoplasique","accept":["vulgaire, superficiel et paranéoplasique","pemphigus vulgaire, superficiel, paranéoplasique"],"keywords":["vulgaire","superficiel","paranéoplasique"],"explanation":"On distingue le pemphigus vulgaire (clivage profond, suprabasal), les pemphigus superficiels (clivage sous-corné) et le pemphigus paranéoplasique.","src":"p. 64"},{"id":"d112-qroc-038","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["clinique"],"difficulty":2,"question":"Quels sont les deux pemphigus superficiels ?","answer":"Le pemphigus séborrhéique et le pemphigus foliacé","accept":["séborrhéique et foliacé","pemphigus séborrhéique et pemphigus foliacé","foliacé et séborrhéique"],"keywords":["séborrh","foliac"],"explanation":"Le pemphigus séborrhéique est la forme localisée (lésions squamo-croûteuses des zones séborrhéiques, bulles très fugaces) ; le pemphigus foliacé est la forme disséminée.","src":"p. 65"},{"id":"d112-qroc-039","type":"QROC","rank":"B","objective":"d112-obj-02","tags":["diagnostic","clinique"],"difficulty":2,"question":"Des lésions en « cocardes » (au moins trois cercles concentriques) de siège acral caractérisent quelle dermatose bulleuse non auto-immune ?","answer":"L'érythème polymorphe (bulleux)","accept":["érythème polymorphe","érythème polymorphe bulleux"],"keywords":["polymorphe"],"explanation":"L'érythème polymorphe bulleux associe des cocardes acrales et des lésions muqueuses fréquentes ; il survient le plus souvent 10 à 15 jours après une infection et guérit spontanément en 2 à 3 semaines.","src":"p. 57"},{"id":"d112-qroc-040","type":"QROC","rank":"B","objective":"d112-obj-02","tags":["étiologie"],"difficulty":2,"question":"Quelle infection précède le plus souvent un érythème polymorphe bulleux ?","answer":"Une récurrence d'herpès","accept":["herpès","récurrence d'herpès","infection herpétique"],"keywords":["herp"],"explanation":"L'érythème polymorphe bulleux survient le plus souvent 10 à 15 jours après une infection, le plus souvent une récurrence d'herpès.","src":"p. 57"},{"id":"d112-qroc-041","type":"QROC","rank":"B","objective":"d112-obj-03","tags":["étiologie"],"difficulty":2,"question":"Quel groupe chimique est commun à plusieurs médicaments inducteurs de pemphigus (D-pénicillamine, captopril...) ?","answer":"Le groupe thiol","accept":["thiol","groupe thiol","médicaments à groupe thiol"],"keywords":["thiol"],"explanation":"Les pemphigus peuvent être déclenchés par des médicaments contenant un groupe thiol (D-pénicillamine, captopril, thiopronine, pyrithioxine) ; l'arrêt du médicament ne suffit pas toujours à enrayer le pemphigus.","src":"p. 64"},{"id":"d112-qcm-101","type":"QRM","rank":"A","objective":"d112-obj-05","tags":["définition","clinique"],"difficulty":1,"stem":"Concernant la bulle, quelles propositions sont exactes ?","options":[{"t":"Elle mesure plus de 5 mm","ok":true,"why":"Une bulle est une lésion liquidienne superficielle de taille supérieure à 5 mm."},{"t":"Une bulle intra-épidermique récente est tendue","ok":false,"why":"Elle est flasque et fragile, car son toit est très fin."},{"t":"Elle peut siéger sur la peau ou sur les muqueuses","ok":true,"why":"Sur les muqueuses externes, les bulles sont toutefois fugaces et rarement vues."},{"t":"Son contenu est toujours purulent","ok":false,"why":"Le contenu est clair ou séro-hématique."},{"t":"Une bulle sous-épidermique récente est tendue","ok":true,"why":"Son toit est constitué par l'épiderme intact."}],"explanation":"Bulle : lésion liquidienne superficielle de plus de 5 mm, au contenu clair ou séro-hématique. Sous-épidermique = tendue ; intra-épidermique = flasque et fragile.","src":"p. 55"},{"id":"d112-qcm-102","type":"QRM","rank":"A","objective":"d112-obj-02","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Concernant l'immunofluorescence directe (IFD) dans les dermatoses bulleuses, quelles propositions sont exactes ?","options":[{"t":"Elle porte sur une biopsie de peau ou de muqueuse périlésionnelle","ok":true,"why":"Elle détecte les anticorps fixés in vivo."},{"t":"Elle recherche dans le sérum des anticorps circulants","ok":false,"why":"L'IFD détecte les anticorps fixés in vivo sur la biopsie ; la recherche d'anticorps sériques relève de l'IFI."},{"t":"Elle objective des dépôts d'IgG et/ou d'IgA et/ou de C3","ok":true,"why":"Ces dépôts prouvent l'origine auto-immune de la maladie bulleuse."},{"t":"Dans le pemphigus, les dépôts sont linéaires le long de la jonction dermo-épidermique","ok":false,"why":"Dans le pemphigus, ils entourent les kératinocytes en mailles de filet."},{"t":"Dans la pemphigoïde bulleuse, les dépôts sont linéaires à la jonction dermo-épidermique","ok":true,"why":"Dépôts linéaires d'IgG et/ou de C3, aspect des DBAI sous-épidermiques."}],"explanation":"L'IFD d'une biopsie périlésionnelle montre des dépôts in vivo d'IgG, d'IgA et/ou de C3 : linéaires à la jonction dermo-épidermique (DBAI sous-épidermiques), en mailles de filet autour des kératinocytes (pemphigus).","src":"p. 56, 59-60"},{"id":"d112-qcm-103","type":"QRM","rank":"A","objective":"d112-obj-04","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Concernant les biopsies à réaliser devant une dermatose bulleuse, quelles propositions sont exactes ?","options":[{"t":"La biopsie pour l'histologie porte sur une bulle cutanée intacte et récente","ok":true,"why":"On peut aussi biopsier le bord d'une érosion muqueuse."},{"t":"La biopsie est inutile si la présentation clinique paraît typique","ok":false,"why":"Le diagnostic nécessite la combinaison de l'examen clinique, de l'histologie et de l'immunopathologie."},{"t":"La biopsie pour l'IFD est prélevée en zone périlésionnelle","ok":true,"why":"Elle montre les anticorps fixés in vivo."},{"t":"La biopsie pour l'IFD se fait au centre d'une bulle ancienne","ok":false,"why":"Elle se fait en peau ou muqueuse périlésionnelle ; la bulle récente et intacte sert à l'histologie."},{"t":"L'histologie distingue un clivage sous-épidermique d'un clivage intra-épidermique","ok":true,"why":"Cette distinction oriente vers le groupe des pemphigoïdes ou celui des pemphigus."}],"explanation":"Deux biopsies : une bulle intacte et récente pour l'histologie (niveau du clivage), la peau périlésionnelle pour l'IFD.","src":"p. 55, 59"},{"id":"d112-qcm-104","type":"QRM","rank":"A","objective":"d112-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Concernant la pemphigoïde bulleuse, quelles propositions sont exactes ?","options":[{"t":"Elle touche surtout les sujets âgés","ok":true,"why":"L'âge moyen est d'environ 80 ans (plus de 70 ans)."},{"t":"Le signe de Nikolsky est positif","ok":false,"why":"Il est absent ; il est positif dans le pemphigus."},{"t":"Elle débute par un prurit généralisé et intense","ok":true,"why":"Avec des placards eczématiformes ou urticariens."},{"t":"L'atteinte muqueuse est constante et inaugurale","ok":false,"why":"Elle est rare, habituellement absente ; elle est inaugurale dans le pemphigus."},{"t":"Les bulles sont tendues, souvent de grande taille","ok":true,"why":"Elles siègent sur une base érythémateuse, eczématiforme ou urticarienne."}],"explanation":"Pemphigoïde bulleuse : sujet âgé, prurit inaugural, bulles tendues sur base érythémateuse ou urticarienne, pas de Nikolsky, atteinte muqueuse rare.","src":"p. 59"},{"id":"d112-qcm-105","type":"QRM","rank":"A","objective":"d112-obj-03","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Concernant le pemphigus (par comparaison à la pemphigoïde bulleuse), quelles propositions sont exactes ?","options":[{"t":"L'histologie montre une bulle sous-épidermique riche en éosinophiles","ok":false,"why":"C'est l'aspect de la pemphigoïde bulleuse ; le pemphigus donne une bulle intra-épidermique."},{"t":"Il survient en moyenne vers 40-50 ans","ok":true,"why":"La pemphigoïde bulleuse survient plutôt après 70 ans."},{"t":"L'atteinte muqueuse est fréquente et souvent inaugurale","ok":true,"why":"Elle est rare dans la pemphigoïde bulleuse."},{"t":"Il débute par un prurit généralisé intense","ok":false,"why":"Il n'y a pas de prodromes dans le pemphigus ; le prurit inaugural est celui de la pemphigoïde bulleuse."},{"t":"Les bulles sont flasques et siègent en peau saine","ok":true,"why":"Dans la pemphigoïde bulleuse, elles sont tendues sur une peau lésée."}],"explanation":"Pemphigus : 40-50 ans, atteinte muqueuse inaugurale, bulles flasques en peau saine, Nikolsky positif, bulle intra-épidermique, IFD en mailles de filet.","src":"p. 59, 64"},{"id":"d112-qcm-106","type":"QRM","rank":"A","objective":"d112-obj-03","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Une femme de 84 ans consulte pour un prurit généralisé intense évoluant depuis 3 semaines, suivi de bulles tendues sur des placards érythémateux de la face interne des cuisses et de l'abdomen. Il n'y a pas d'atteinte muqueuse. Quelles propositions sont exactes ?","options":[{"t":"Le diagnostic le plus probable est une pemphigoïde bulleuse","ok":true,"why":"Âge, prurit, bulles tendues sur base érythémateuse, atteinte muqueuse absente."},{"t":"Le signe de Nikolsky est attendu positif, avec décollement de la peau saine","ok":false,"why":"Il est absent dans la pemphigoïde bulleuse."},{"t":"L'IFD montre des dépôts linéaires d'IgG et/ou de C3 à la jonction dermo-épidermique","ok":true,"why":"C'est l'aspect des DBAI sous-épidermiques."},{"t":"L'histologie montre une bulle intra-épidermique avec acantholyse","ok":false,"why":"Il n'y a pas d'acantholyse dans la pemphigoïde bulleuse : le clivage est sous-épidermique."},{"t":"L'histologie montre une bulle sous-épidermique contenant des éosinophiles","ok":true,"why":"Avec un infiltrat dermique riche en éosinophiles ; une hyperéosinophilie sanguine est fréquente."}],"explanation":"Sujet âgé, prurit puis bulles tendues sur peau érythémateuse, pas de muqueuse : pemphigoïde bulleuse (bulle sous-épidermique à éosinophiles, IFD linéaire).","src":"p. 59-60"},{"id":"d112-qcm-107","type":"QRM","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"stem":"À propos de la prise en charge thérapeutique d'une pemphigoïde bulleuse, quelles propositions sont exactes ?","options":[{"t":"L'hydratation doit se faire systématiquement par voie veineuse","ok":false,"why":"On s'efforce de ne pas utiliser la voie veineuse, en raison du risque infectieux."},{"t":"Le propionate de clobétasol local (20 à 40 g/jour) est un traitement possible","ok":true,"why":"La corticothérapie est ensuite diminuée progressivement par paliers, sur 6 à 12 mois."},{"t":"La corticothérapie locale forte est moins efficace que la corticothérapie générale","ok":false,"why":"Son efficacité est similaire, avec une meilleure tolérance."},{"t":"La corticothérapie locale forte est mieux tolérée que la corticothérapie générale","ok":true,"why":"Moins d'effets secondaires et baisse de la mortalité."},{"t":"Les mesures générales comportent des bains antiseptiques, une hydratation et une nutrition hypercalorique","ok":true,"why":"Ce sont les mesures propres à toute maladie bulleuse."}],"explanation":"Pemphigoïde bulleuse : clobétasol local (20-40 g/jour, 6-12 mois), aussi efficace et mieux toléré que la corticothérapie générale ; mesures générales (bains antiseptiques, hydratation, nutrition hypercalorique).","src":"p. 61"},{"id":"d112-qcm-108","type":"QRM","rank":"A","objective":"d112-obj-03","tags":["complications","suivi"],"difficulty":2,"stem":"Concernant le pronostic et la surveillance de la pemphigoïde bulleuse, quelles propositions sont exactes ?","options":[{"t":"Le pronostic est bénin, sans surmortalité chez le sujet âgé","ok":false,"why":"C'est une maladie grave."},{"t":"La mortalité à 1 an est de 30 à 40 %","ok":true,"why":"Elle est liée au terrain âgé et aux traitements."},{"t":"Les décès sont surtout dus à l'extension des lésions cutanées","ok":false,"why":"Ils sont principalement dus aux complications infectieuses ou cardiovasculaires."},{"t":"Les décès sont surtout liés à des complications infectieuses ou cardiovasculaires","ok":true,"why":"Elles sont favorisées par le traitement corticoïde et/ou immunosuppresseur et par le terrain."},{"t":"La tolérance de la corticothérapie est à surveiller (poids, pression artérielle, infections, diabète)","ok":true,"why":"La morbidité et la mortalité iatrogènes sont majeures à cet âge."}],"explanation":"Pemphigoïde bulleuse : mortalité de 30 à 40 % à 1 an, par complications infectieuses ou cardiovasculaires favorisées par les traitements et le terrain ; surveillance de la tolérance des corticoïdes.","src":"p. 61"},{"id":"d112-qcm-109","type":"QRM","rank":"A","objective":"d112-obj-06","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Un homme de 45 ans présente depuis 2 mois des érosions buccales douloureuses et traînantes, gênant l'alimentation, avec un amaigrissement. Des bulles flasques en peau saine sont apparues sur le thorax, laissant des érosions, avec un signe de Nikolsky positif. Quelles propositions sont exactes ?","options":[{"t":"Le diagnostic le plus probable est un pemphigus vulgaire","ok":true,"why":"Début muqueux, puis bulles flasques en peau saine et signe de Nikolsky."},{"t":"L'IFD montre des dépôts linéaires le long de la jonction dermo-épidermique","ok":false,"why":"L'aspect linéaire est celui des DBAI sous-épidermiques ; ici, mailles de filet."},{"t":"L'histologie montre une bulle intra-épidermique suprabasale avec acantholyse","ok":true,"why":"Les kératinocytes sont détachés les uns des autres."},{"t":"Le traitement d'attaque repose sur le clobétasol local seul","ok":false,"why":"Le traitement d'attaque du pemphigus est une corticothérapie générale à forte dose (prednisone 1 à 1,5 mg/kg/jour)."},{"t":"L'IFD montre des dépôts d'IgG et de C3 en mailles de filet","ok":true,"why":"Les dépôts entourent les kératinocytes (aspect en résille)."}],"explanation":"Érosions buccales inaugurales puis bulles flasques en peau saine avec Nikolsky : pemphigus vulgaire (bulle suprabasale avec acantholyse, IFD en mailles de filet).","src":"p. 64, 66-67"},{"id":"d112-qcm-110","type":"QRM","rank":"A","objective":"d112-obj-03","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant le traitement des principales dermatoses bulleuses auto-immunes, quelles propositions sont exactes ?","options":[{"t":"Il repose essentiellement sur la corticothérapie locale ou générale","ok":true,"why":"Locale ou générale selon la maladie."},{"t":"La corticothérapie locale forte est le traitement d'attaque habituel du pemphigus","ok":false,"why":"Elle est utilisée dans la pemphigoïde bulleuse ; le pemphigus relève d'une corticothérapie générale forte."},{"t":"Le traitement d'attaque du pemphigus est une corticothérapie générale à forte dose","ok":true,"why":"Prednisone 1 à 1,5 mg/kg/jour."},{"t":"Ces traitements sont dénués de complications iatrogènes","ok":false,"why":"Ils peuvent être à l'origine de complications iatrogènes."},{"t":"La mortalité du pemphigus, autour de 10 %, est principalement iatrogène","ok":true,"why":"Elle est surtout due aux complications du traitement."}],"explanation":"Corticothérapie locale (pemphigoïde bulleuse) ou générale (pemphigus : prednisone 1-1,5 mg/kg/jour) ; la mortalité du pemphigus (~10 %) est surtout iatrogène.","src":"p. 61, 67"},{"id":"d112-qcm-111","type":"QRM","rank":"A","objective":"d112-obj-02","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Quels éléments orientent vers une toxidermie bulleuse (syndromes de Lyell et de Stevens-Johnson) plutôt que vers une dermatose bulleuse auto-immune ?","options":[{"t":"Un début brutal et une évolution rapide","ok":true,"why":"Ce sont des caractères de la toxidermie bulleuse."},{"t":"Des dépôts d'IgG et de C3 en IFD sur la biopsie périlésionnelle","ok":false,"why":"Les maladies bulleuses non auto-immunes se reconnaissent à la négativité des examens immunopathologiques, en particulier de l'IFD."},{"t":"Des signes généraux imposant une hospitalisation en urgence","ok":true,"why":"La toxidermie bulleuse est une urgence."},{"t":"Une atteinte muqueuse fréquente, souvent inaugurale","ok":true,"why":"À la différence de la pemphigoïde bulleuse (atteinte muqueuse rare)."},{"t":"La prise de médicaments dans le délai d'imputabilité","ok":true,"why":"C'est le critère d'imputabilité (voir l'item sur les toxidermies)."}],"explanation":"Toxidermie bulleuse : début brutal, évolution rapide, signes généraux (hospitalisation en urgence), atteinte muqueuse fréquente, médicament imputable ; IFD négative.","src":"p. 56"},{"id":"d112-qcm-112","type":"QRM","rank":"A","objective":"d112-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Devant quelles lésions faut-il évoquer une dermatose bulleuse ?","options":[{"t":"Des érosions cutanées post-bulleuses arrondies, parfois croûteuses","ok":true,"why":"Elles témoignent de bulles rompues."},{"t":"Un érythème isolé, sans décollement ni érosion","ok":false,"why":"Il faut des bulles, des érosions post-bulleuses ou muqueuses, un décollement ou un signe de Nikolsky."},{"t":"Des érosions des muqueuses externes","ok":true,"why":"Les bulles y sont fugaces et rarement vues."},{"t":"Un vaste décollement épidermique en « linge mouillé »","ok":true,"why":"C'est un aspect de décollement épidermique étendu."},{"t":"Un signe de Nikolsky","ok":true,"why":"Décollement provoqué par un frottement appuyé sur la peau saine."}],"explanation":"On évoque une dermatose bulleuse devant des bulles, des érosions post-bulleuses ou muqueuses, un décollement en linge mouillé ou un signe de Nikolsky.","src":"p. 55"},{"id":"d112-qcm-113","type":"QRM","rank":"B","objective":"d112-obj-03","tags":["physiopathologie","diagnostic"],"difficulty":2,"stem":"Concernant la classification des dermatoses bulleuses auto-immunes, quelles propositions sont exactes ?","options":[{"t":"Les pemphigus sont des DBAI intra-épidermiques","ok":true,"why":"L'altération des desmosomes par des autoanticorps provoque une acantholyse."},{"t":"La pemphigoïde bulleuse est due à des anticorps anti-substance intercellulaire","ok":false,"why":"Elle est due à des anticorps anti-membrane basale (dermatose sous-épidermique)."},{"t":"Les pemphigoïdes sont des DBAI sous-épidermiques","ok":true,"why":"Perte d'adhérence dermo-épidermique par altération d'un composant de la jonction dermo-épidermique."},{"t":"Le pemphigus paranéoplasique est le plus fréquent des pemphigus","ok":false,"why":"C'est une forme exceptionnelle de pemphigus."},{"t":"Le pemphigus vulgaire donne un clivage suprabasal et les pemphigus superficiels un clivage sous-corné","ok":true,"why":"Clivage profond pour le pemphigus vulgaire, superficiel pour les pemphigus superficiels."}],"explanation":"Pemphigus = intra-épidermique (desmosomes, acantholyse, anti-SIC) ; pemphigoïdes = sous-épidermique (jonction dermo-épidermique, anti-membrane basale).","src":"p. 55, 64, 66"},{"id":"d112-qcm-114","type":"QRM","rank":"B","objective":"d112-obj-03","tags":["physiopathologie","biologie"],"difficulty":2,"stem":"Concernant les anticorps et les cibles antigéniques des dermatoses bulleuses auto-immunes, quelles propositions sont exactes ?","options":[{"t":"La cible du pemphigus vulgaire est la desmogléine 3","ok":true,"why":"La desmogléine 1 est celle du pemphigus superficiel."},{"t":"Dans le pemphigus, les anticorps sont de type anti-membrane basale","ok":false,"why":"Ce sont des anticorps anti-substance intercellulaire (anti-SIC)."},{"t":"La cible du pemphigus superficiel est la desmogléine 1","ok":true,"why":"Mise en évidence par immunotransfert ou ELISA."},{"t":"Dans la pemphigoïde bulleuse, le titre des anticorps anti-membrane basale est corrélé à la sévérité","ok":false,"why":"Le titre n'est pas lié à la sévérité ni à l'étendue ; dans le pemphigus, le titre des anti-SIC est corrélé à l'activité."},{"t":"Les cibles de la pemphigoïde bulleuse sont BP230 et BP180","ok":true,"why":"BPAG1 (BP230) et BPAG2 (BP180)."}],"explanation":"PV : desmogléine 3 ; pemphigus superficiel : desmogléine 1 ; pemphigoïde bulleuse : BP230/BP180. Sérum : anti-SIC (pemphigus), anti-membrane basale (pemphigoïde).","src":"p. 58-60, 66"},{"id":"d112-qcm-115","type":"QRM","rank":"B","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement du pemphigus, quelles propositions sont exactes ?","options":[{"t":"Le rituximab est un anticorps monoclonal dirigé contre le CD3","ok":false,"why":"Il cible le CD20."},{"t":"Le rituximab peut être proposé en première intention","ok":true,"why":"Anticorps monoclonal anti-CD20."},{"t":"Le rituximab permet de réduire la dose et la durée de la corticothérapie","ok":true,"why":"Et donc de réduire ses effets secondaires."},{"t":"La prednisone est utilisée à 0,5 à 0,75 mg/kg/jour","ok":false,"why":"La dose d'attaque est de 1 à 1,5 mg/kg/jour (0,5-0,75 mg/kg/jour concerne une pemphigoïde bulleuse limitée)."},{"t":"Des immunosuppresseurs sont parfois associés en cas de résistance à la corticothérapie","ok":true,"why":"Azathioprine, cyclophosphamide ou ciclosporine."}],"explanation":"Pemphigus : prednisone 1-1,5 mg/kg/jour ; rituximab (anti-CD20) possible d'emblée ; immunosuppresseurs si résistance.","src":"p. 61, 67"},{"id":"d112-qcm-116","type":"QRM","rank":"B","objective":"d112-obj-02","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Concernant l'érythème polymorphe bulleux, quelles propositions sont exactes ?","options":[{"t":"Les lésions cutanées sont en « cocardes » d'au moins trois cercles concentriques","ok":true,"why":"Ce sont des lésions éruptives caractéristiques."},{"t":"Il évolue vers une chronicité avec des poussées répétées sur plusieurs années","ok":false,"why":"L'évolution est spontanément favorable, avec guérison en 2 à 3 semaines."},{"t":"Les lésions siègent de façon acrale (coudes, genoux, mains, visage)","ok":true,"why":"Disposition acrale."},{"t":"Les muqueuses sont épargnées, les lésions restant strictement cutanées","ok":false,"why":"Les lésions muqueuses bulleuses ou érosives sont fréquentes (buccales, génitales, conjonctivales)."},{"t":"Il survient 10 à 15 jours après une infection, souvent herpétique","ok":true,"why":"C'est le contexte habituel."}],"explanation":"Érythème polymorphe bulleux : cocardes acrales, muqueuses fréquemment atteintes, 10-15 jours après une infection (herpès), guérison en 2-3 semaines.","src":"p. 57"},{"id":"d112-qru-101","type":"QRU","rank":"A","objective":"d112-obj-05","tags":["clinique","physiopathologie"],"difficulty":1,"stem":"Un frottement appuyé sur la peau saine d'un patient provoque un décollement cutané. Que traduit ce signe de Nikolsky ?","options":[{"t":"Un clivage sous-épidermique","ok":false,"why":"Le signe de Nikolsky est absent des pemphigoïdes, dont le clivage est sous-épidermique."},{"t":"Un dépôt linéaire d'IgG à la jonction dermo-épidermique","ok":false,"why":"C'est l'aspect de l'IFD des DBAI sous-épidermiques."},{"t":"Un décollement intra-épidermique (acantholyse)","ok":true,"why":"Il est positif dans le pemphigus."},{"t":"Une infiltration dermique à éosinophiles","ok":false,"why":"C'est l'histologie de la pemphigoïde bulleuse."},{"t":"Une érosion muqueuse inaugurale","ok":false,"why":"C'est une autre manifestation (pemphigus vulgaire) ; le signe de Nikolsky est un test cutané."}],"explanation":"Le signe de Nikolsky traduit un décollement intra-épidermique (acantholyse) : il est positif dans le pemphigus.","src":"p. 55"},{"id":"d112-qru-102","type":"QRU","rank":"A","objective":"d112-obj-02","tags":["diagnostic","paraclinique"],"difficulty":1,"stem":"Quel examen permet de mettre en évidence l'origine auto-immune d'une maladie bulleuse ?","options":[{"t":"La numération-formule sanguine avec recherche d'une hyperéosinophilie","ok":false,"why":"L'hyperéosinophilie est fréquente dans la pemphigoïde bulleuse mais ne prouve pas l'origine auto-immune."},{"t":"L'immunofluorescence directe de la peau périlésionnelle","ok":true,"why":"Elle objective des dépôts in vivo d'IgG, d'IgA et/ou de C3."},{"t":"L'histologie standard d'une biopsie de bulle récente","ok":false,"why":"Elle distingue le niveau de clivage mais ne prouve pas l'origine auto-immune."},{"t":"Le signe de Nikolsky recherché sur la peau saine","ok":false,"why":"C'est un signe clinique traduisant un décollement intra-épidermique."},{"t":"Un prélèvement bactériologique du liquide de la bulle","ok":false,"why":"Il ne renseigne pas sur l'origine auto-immune."}],"explanation":"L'immunofluorescence directe d'une biopsie de peau ou de muqueuse périlésionnelle met en évidence l'origine auto-immune.","src":"p. 56"},{"id":"d112-qru-103","type":"QRU","rank":"A","objective":"d112-obj-03","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Une femme de 85 ans présente un prurit généralisé intense puis des bulles tendues sur base érythémateuse des faces de flexion des membres, sans atteinte muqueuse ni signe de Nikolsky. Quel est le diagnostic le plus probable ?","options":[{"t":"Un pemphigus vulgaire","ok":false,"why":"Il débute par des érosions muqueuses, avec des bulles flasques et un signe de Nikolsky positif."},{"t":"Un érythème polymorphe bulleux","ok":false,"why":"Il associe des cocardes acrales et des lésions muqueuses, après une infection."},{"t":"Une pemphigoïde bulleuse","ok":true,"why":"DBAI la plus fréquente du sujet âgé : prurit, bulles tendues, pas de Nikolsky, muqueuses épargnées."},{"t":"Une toxidermie bulleuse","ok":false,"why":"Elle a un début brutal, des signes généraux et une atteinte muqueuse fréquente."},{"t":"Un pemphigus foliacé","ok":false,"why":"Les pemphigus sont des DBAI intra-épidermiques, avec bulles flasques et signe de Nikolsky."}],"explanation":"Sujet âgé, prurit, bulles tendues sur base érythémateuse, pas de Nikolsky ni d'atteinte muqueuse : pemphigoïde bulleuse.","src":"p. 59"},{"id":"d112-qru-104","type":"QRU","rank":"A","objective":"d112-obj-03","tags":["clinique"],"difficulty":2,"stem":"Quelle est la topographie habituelle des lésions de la pemphigoïde bulleuse ?","options":[{"t":"Les plis de flexion, les zones de frottement et le cuir chevelu","ok":false,"why":"C'est la topographie préférentielle du pemphigus."},{"t":"Les faces d'extension des membres, de façon symétrique","ok":false,"why":"Cette topographie évoque plutôt une dermatite herpétiforme ou une épidermolyse bulleuse acquise."},{"t":"Racine et faces de flexion des membres, cuisses, abdomen","ok":true,"why":"Les lésions sont symétriques, avec cette prédilection."},{"t":"La muqueuse buccale, de façon exclusive et inaugurale","ok":false,"why":"L'atteinte muqueuse est rare, habituellement absente."},{"t":"Des lésions asymétriques unilatérales du tronc","ok":false,"why":"Les lésions sont symétriques."}],"explanation":"La pemphigoïde bulleuse donne des lésions symétriques, prédominant à la racine et aux faces de flexion des membres, à la face antéro-interne des cuisses et à l'abdomen.","src":"p. 58-59"},{"id":"d112-qru-105","type":"QRU","rank":"A","objective":"d112-obj-06","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Un homme de 45 ans présente depuis 2 mois des érosions buccales douloureuses, d'apparition insidieuse, gênant l'alimentation. Quelle dermatose bulleuse auto-immune faut-il évoquer en premier ?","options":[{"t":"Une pemphigoïde bulleuse","ok":false,"why":"L'atteinte muqueuse est rare, habituellement absente."},{"t":"Un pemphigus séborrhéique","ok":false,"why":"Il n'existe habituellement pas d'atteinte muqueuse."},{"t":"Un pemphigus paranéoplasique","ok":false,"why":"C'est une forme exceptionnelle de pemphigus."},{"t":"Un pemphigus vulgaire","ok":true,"why":"Il débute souvent de façon insidieuse par des érosions buccales douloureuses, avec dysphagie."},{"t":"Une pemphigoïde gravidique","ok":false,"why":"Elle survient lors de la grossesse ou du post-partum."}],"explanation":"Des érosions buccales douloureuses d'apparition insidieuse évoquent d'abord un pemphigus vulgaire.","src":"p. 62, 64-65"},{"id":"d112-qru-106","type":"QRU","rank":"A","objective":"d112-obj-03","tags":["traitement"],"difficulty":2,"stem":"Une pemphigoïde bulleuse étendue est diagnostiquée chez un sujet de 82 ans. Quel traitement, d'efficacité similaire à la corticothérapie générale mais mieux toléré, est utilisé ?","options":[{"t":"Le rituximab en première intention","ok":false,"why":"Il est proposé dans le pemphigus."},{"t":"La prednisone à 1 à 1,5 mg/kg/jour","ok":false,"why":"C'est la dose d'attaque du pemphigus."},{"t":"Un antibiotique par voie veineuse","ok":false,"why":"On s'efforce d'éviter la voie veineuse (risque infectieux) et les antibiotiques ne traitent pas la maladie."},{"t":"Des bains antiseptiques seuls","ok":false,"why":"Ils font partie des mesures générales mais ne remplacent pas la corticothérapie."},{"t":"Le propionate de clobétasol local","ok":true,"why":"Corticothérapie locale forte de 20 à 40 g/jour, meilleure tolérance et baisse de la mortalité."}],"explanation":"Pemphigoïde bulleuse : corticothérapie locale forte par propionate de clobétasol, aussi efficace que la corticothérapie générale et mieux tolérée.","src":"p. 61"},{"id":"d112-qru-107","type":"QRU","rank":"B","objective":"d112-obj-03","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Un patient présente des lésions squamo-croûteuses, parfois prurigineuses, du visage, du cuir chevelu, de la face antérieure du thorax et de la région interscapulaire. Les bulles sont très fugaces et inconstantes, sans atteinte muqueuse. Quel est le diagnostic ?","options":[{"t":"Un pemphigus vulgaire","ok":false,"why":"Il débute par des érosions muqueuses, avec des bulles flasques en peau saine."},{"t":"Une pemphigoïde bulleuse","ok":false,"why":"Sujet âgé, prurit, bulles tendues de grande taille sur peau érythémateuse."},{"t":"Un pemphigus paranéoplasique","ok":false,"why":"C'est une forme exceptionnelle de pemphigus, de nature paranéoplasique."},{"t":"Un pemphigus séborrhéique","ok":true,"why":"Pemphigus superficiel localisé sur les zones séborrhéiques, sans atteinte muqueuse habituelle."},{"t":"Un érythème polymorphe bulleux","ok":false,"why":"Il associe des cocardes acrales et des lésions muqueuses fréquentes."}],"explanation":"Lésions squamo-croûteuses des zones séborrhéiques, bulles fugaces et pas de muqueuse : pemphigus séborrhéique (pemphigus superficiel localisé).","src":"p. 65"},{"id":"d112-qru-108","type":"QRU","rank":"B","objective":"d112-obj-02","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Quelle dermatose bulleuse non auto-immune est caractérisée par des lésions en « cocardes » acrales, des lésions muqueuses fréquentes et une survenue après une récurrence d'herpès ?","options":[{"t":"La pemphigoïde bulleuse","ok":false,"why":"Dermatose auto-immune du sujet âgé, avec atteinte muqueuse rare."},{"t":"Le pemphigus vulgaire","ok":false,"why":"Dermatose auto-immune débutant par des érosions muqueuses, sans cocardes."},{"t":"La toxidermie bulleuse","ok":false,"why":"Début brutal, signes généraux et prise de médicaments dans le délai d'imputabilité."},{"t":"Une dermatose bulleuse par agent externe","ok":false,"why":"Cause physique ou chimique, dont le diagnostic repose sur l'anamnèse."},{"t":"L'érythème polymorphe bulleux","ok":true,"why":"Cocardes d'au moins 3 cercles concentriques, 10-15 jours après une infection, guérison en 2 à 3 semaines."}],"explanation":"Cocardes acrales, muqueuses atteintes, contexte post-herpétique : érythème polymorphe bulleux.","src":"p. 57"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d112-pareto","points":[{"id":"d112-par-01","rank":"A","cat":"examen","text":"Diagnostic d'une DBAI = **clinique** + **histologie** (bulle intacte et récente) + **immunofluorescence directe** (peau périlésionnelle) ; forme étendue ou rapide → **hospitalisation**","src":"p. 55, 58-59, 67"},{"id":"d112-par-02","rank":"A","cat":"clinique","text":"Bulle > **5 mm** : sous-épidermique = **tendue** ; intra-épidermique = **flasque** et fragile ; **Nikolsky** = décollement intra-épidermique (acantholyse), positif dans le **pemphigus**","src":"p. 55"},{"id":"d112-par-03","rank":"A","cat":"examen","text":"IFD (IgG, IgA, C3) : dépôts **linéaires** le long de la jonction dermo-épidermique (pemphigoïdes) ; en **mailles de filet** autour des kératinocytes (pemphigus)","src":"p. 56"},{"id":"d112-par-04","rank":"A","cat":"clinique","text":"**Pemphigoïde bulleuse** = DBAI la plus fréquente, sujet **âgé** (~80 ans) : **prurit** puis bulles **tendues** sur peau érythémateuse, **Nikolsky −**, muqueuses rarement atteintes","src":"p. 59"},{"id":"d112-par-05","rank":"A","cat":"clinique","text":"**Pemphigus vulgaire** (40-50 ans) : débute par **érosions buccales** (dysphagie), puis bulles **flasques** en peau saine, **Nikolsky +** ; auto-anticorps anti-**desmosomes** → acantholyse","src":"p. 59, 64"},{"id":"d112-par-06","rank":"A","cat":"traitement","text":"PB : **clobétasol** local 20-40 g/j (6-12 mois), aussi efficace que la corticothérapie générale et **mieux toléré** ; prednisone 0,5-0,75 mg/kg/j possible si < 10 bulles/j","src":"p. 61"},{"id":"d112-par-07","rank":"A","cat":"gravité","text":"PB = maladie grave : mortalité **30-40 % à 1 an** (infections, complications cardiovasculaires) ; surveiller la tolérance des corticoïdes ; bains antiseptiques, hydratation, nutrition **hypercalorique**","src":"p. 61"},{"id":"d112-par-08","rank":"A","cat":"traitement","text":"Pemphigus : **prednisone 1-1,5 mg/kg/j** (corticothérapie générale forte) d'emblée ; mortalité ~**10 %**, surtout **iatrogène** (complications du traitement)","src":"p. 67"},{"id":"d112-par-09","rank":"A","cat":"examen","text":"Histologie : PB = bulle **sous-épidermique à éosinophiles** (hyperéosinophilie fréquente), sans acantholyse ; pemphigus = bulle **intra-épidermique** (suprabasale dans le PV) avec acantholyse","src":"p. 60, 66"},{"id":"d112-par-10","rank":"A","cat":"piège","text":"DD urgent : **toxidermie bulleuse** (Lyell, Stevens-Johnson) = début brutal, signes généraux, atteinte muqueuse inaugurale, médicament imputable ; **IFD négative**","src":"p. 56"},{"id":"d112-par-11","rank":"B","cat":"chiffre","text":"Cibles : **PV = desmogléine 3**, pemphigus superficiel = **desmogléine 1**, PB = **BP230/BP180** ; sérum : anti-**SIC** (pemphigus) vs anti-**membrane basale** (PB)","src":"p. 56, 58-59, 66"},{"id":"d112-par-12","rank":"B","cat":"clinique","text":"Pemphigus : **vulgaire** (suprabasal), **superficiels** (séborrhéique, foliacé ; sous-corné), paranéoplasique ; **rituximab** (anti-CD20) possible en 1re intention ; inducteurs : groupe **thiol**","src":"p. 64-65, 67"},{"id":"d112-par-13","rank":"B","cat":"clinique","text":"**Érythème polymorphe bulleux** : **cocardes** (≥ 3 cercles) acrales, muqueuses fréquentes, 10-15 j après une infection (**herpès**), guérison en 2-3 semaines","src":"p. 57"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
